use serde::{Deserialize, Serialize}; use serde_json::Value; use std::collections::BTreeMap;  #[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "snake_case")] pub enum ProtocolVersion {     V1, }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] pub struct ThreadId(pub String);  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] pub struct TurnId(pub String);  #[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "snake_case")] pub enum ProtocolRole {     System,     Developer,     User,     Assistant,     Tool, }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] #[serde(tag = "type", rename_all = "snake_case")] pub enum ContentItem {     InputText {         text: String,     },     OutputText {         text: String,     },     InputImage {         image_url: String,         detail: Option<String>,     },     LocalImage {         path: String,     }, }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] #[serde(tag = "type", rename_all = "snake_case")] pub enum InputItem {     Message {         role: ProtocolRole,         content: String,     },     ToolResult {         call_id: Option<String>,         content: String,     },     LocalContext {         name: String,         content: String,     },     ResponseMessage {         id: Option<String>,         role: ProtocolRole,         content: Vec<ContentItem>,     },     FunctionCallOutput {         call_id: String,         output: FunctionCallOutput,     },     McpToolCallOutput {         call_id: String,         output: FunctionCallOutput,     },     CustomToolCallOutput {         call_id: String,         output: FunctionCallOutput,     },     ToolSearchOutput {         call_id: String,         output: String,     }, }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] #[serde(tag = "type", rename_all = "snake_case")] pub enum ResponseItem {     Message {         role: ProtocolRole,         content: String,     },     Reasoning {         content: String,     },     ToolCall {         call: ToolCall,     },     Usage {         input_tokens: i64,         cached_input_tokens: i64,         output_tokens: i64,         reasoning_output_tokens: i64,     },     AgentMessage {         id: String,         content: Vec<ContentItem>,         phase: MessagePhase,     },     ReasoningItem {         id: String,         summary_text: Vec<String>,         raw_content: Vec<String>,     },     LocalShellCall {         id: String,         status: ToolCallStatus,         command: Vec<String>,     },     FunctionCall {         id: String,         call_id: String,         name: String,         arguments: String,         status: ToolCallStatus,     },     FunctionCallOutput {         id: String,         call_id: String,         output: FunctionCallOutput,     },     McpToolCall {         id: String,         call_id: String,         server: String,         tool: String,         arguments: String,         status: ToolCallStatus,     },     ToolSearchCall {         id: String,         call_id: String,         query: String,         status: ToolCallStatus,     },     WebSearchCall {         id: String,         query: String,         status: ToolCallStatus,     },     Compaction {         id: String,         summary: String,     },     CompactionTrigger {         id: String,         reason: String,     }, }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "snake_case")] pub enum MessagePhase {     Created,     Delta,     Completed, }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "snake_case")] pub enum ToolCallStatus {     InProgress,     Completed,     Failed,     Cancelled, }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] #[serde(tag = "type", rename_all = "snake_case")] pub enum FunctionCallOutput {     Text { text: String },     ContentItems { items: Vec<ContentItem> },     Json { value: Value }, }  impl FunctionCallOutput {     pub fn text(text: impl Into<String>) -> Self {         Self::Text { text: text.into() }     } }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] #[serde(tag = "type", rename_all = "snake_case")] pub enum ResponseItemDelta {     MessageContent {         item_id: Option<String>,         delta: String,     },     ReasoningContent {         item_id: Option<String>,         delta: String,     },     ToolCallArguments {         call_id: Option<String>,         delta: String,     },     ToolCallName {         call_id: Option<String>,         name: String,     },     ToolCallStatus {         call_id: Option<String>,         status: ToolCallStatus,     },     ToolOutput {         call_id: Option<String>,         delta: String,     }, }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] pub struct TurnMetadata {     pub thread_id: ThreadId,     pub turn_id: TurnId,     pub session_id: Option<String>,     pub parent_thread_id: Option<ThreadId>,     pub forked_from_thread_id: Option<ThreadId>,     pub model: Option<String>,     pub provider: Option<String>,     pub cwd: String,     pub approval_mode: Option<String>,     pub sandbox_mode: Option<String>,     pub turn_started_at_unix_ms: Option<i64>,     pub workspaces: BTreeMap<String, WorkspaceMetadata>,     pub extra: BTreeMap<String, String>, }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] pub struct ThreadState {     pub thread_id: ThreadId,     pub session_id: Option<String>,     pub parent_thread_id: Option<ThreadId>,     pub status: String,     pub cwd: String,     pub resume_source: Option<String>,     pub child_depth: usize,     #[serde(default)]     pub data: BTreeMap<String, String>, }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] pub struct TurnState {     pub phase: String,     pub status: String,     pub provider_status: String,     pub tool_loop_status: String,     pub cancellation_state: String,     #[serde(default)]     pub data: BTreeMap<String, String>, }  impl TurnMetadata {     pub fn new(thread_id: ThreadId, turn_id: TurnId, cwd: impl Into<String>) -> Self {         Self {             thread_id,             turn_id,             session_id: None,             parent_thread_id: None,             forked_from_thread_id: None,             model: None,             provider: None,             cwd: cwd.into(),             approval_mode: None,             sandbox_mode: None,             turn_started_at_unix_ms: None,             workspaces: BTreeMap::new(),             extra: BTreeMap::new(),         }     } }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] pub struct WorkspaceMetadata {     pub associated_remote_urls: Option<BTreeMap<String, String>>,     pub latest_git_commit_hash: Option<String>,     pub has_changes: Option<bool>, }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "snake_case")] pub enum ResponseStatus {     InProgress,     Completed,     Failed,     Cancelled, }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] #[serde(tag = "type", rename_all = "snake_case")] pub enum StreamEvent {     ResponseStarted {         thread_id: ThreadId,         turn_id: TurnId,         metadata: Option<TurnMetadata>,     },     ItemStarted {         thread_id: ThreadId,         turn_id: TurnId,         item: ResponseItem,     },     ItemDelta {         thread_id: ThreadId,         turn_id: TurnId,         delta: ResponseItemDelta,     },     ItemCompleted {         thread_id: ThreadId,         turn_id: TurnId,         item: ResponseItem,     },     ResponseCompleted {         thread_id: ThreadId,         turn_id: TurnId,         status: ResponseStatus,     },     ResponseCancelled {         thread_id: ThreadId,         turn_id: TurnId,         reason: Option<String>,     },     ResponseFailed {         thread_id: ThreadId,         turn_id: TurnId,         message: String,     }, }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "snake_case")] pub enum ToolCall {     Shell {         id: Option<String>,         command: String,     },     Patch {         id: Option<String>,         patch: String,     },     Mcp {         id: Option<String>,         server: String,         tool: String,         arguments_json: Option<String>,     },     Skill {         id: Option<String>,         name: String,         arguments_json: Option<String>,     },     MultiAgent {         id: Option<String>,         action: String,         arguments_json: Option<String>,     },     ToolSearch {         id: Option<String>,         query: String,     },     RequestUserInput {         id: Option<String>,         prompt: String,     },     ViewImage {         id: Option<String>,         path: String,     }, }  impl ToolCall {     pub fn id(&self) -> Option<&str> {         match self {             Self::Shell { id, .. }             | Self::Patch { id, .. }             | Self::Mcp { id, .. }             | Self::Skill { id, .. }             | Self::MultiAgent { id, .. }             | Self::ToolSearch { id, .. }             | Self::RequestUserInput { id, .. }             | Self::ViewImage { id, .. } => id.as_deref(),         }     } }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] #[serde(tag = "type", rename_all = "snake_case")] pub enum RuntimeEvent {     ThreadStarted {         thread_id: ThreadId,     },     ThreadState {         thread_id: ThreadId,         state: ThreadState,     },     TurnMetadata {         thread_id: ThreadId,         turn_id: TurnId,         metadata: TurnMetadata,     },     TurnStarted {         thread_id: ThreadId,         turn_id: TurnId,     },     TurnState {         thread_id: ThreadId,         turn_id: TurnId,         state: TurnState,     },     DeepParityState {         thread_id: ThreadId,         turn_id: TurnId,         layer: String,         status: String,         message: Option<String>,         #[serde(default)]         data: BTreeMap<String, String>,     },     SandboxAttempt {         thread_id: ThreadId,         turn_id: TurnId,         call_id: Option<String>,         platform: String,         status: String,         backend: String,         command: Option<String>,         cwd: String,         message: Option<String>,     },     ApprovalCacheState {         thread_id: ThreadId,         turn_id: TurnId,         session_id: Option<String>,         tool_name: String,         key: String,         decision: String,         reused: bool,     },     Item {         thread_id: ThreadId,         turn_id: TurnId,         item: ResponseItem,     },     ItemDelta {         thread_id: ThreadId,         turn_id: TurnId,         delta: ResponseItemDelta,     },     Stream {         event: StreamEvent,     },     ToolStarted {         thread_id: ThreadId,         turn_id: TurnId,         call: ToolCall,     },     ToolCompleted {         thread_id: ThreadId,         turn_id: TurnId,         call_id: Option<String>,         output: String,         success: bool,     },     ApprovalRequested {         thread_id: ThreadId,         turn_id: TurnId,         call_id: Option<String>,         tool_name: String,         reason: String,     },     ApprovalCompleted {         thread_id: ThreadId,         turn_id: TurnId,         call_id: Option<String>,         approved: bool,         reason: Option<String>,     },     EscalationRequested {         thread_id: ThreadId,         turn_id: TurnId,         call_id: Option<String>,         tool_name: String,         reason: String,         required_sandbox: Option<String>,         required_network: Option<String>,     },     EscalationCompleted {         thread_id: ThreadId,         turn_id: TurnId,         call_id: Option<String>,         approved: bool,         reason: Option<String>,     },     McpSession {         thread_id: ThreadId,         turn_id: TurnId,         server: String,         status: String,         message: Option<String>,     },     MultiAgent {         thread_id: ThreadId,         turn_id: TurnId,         agent_id: String,         parent_agent_id: Option<String>,         status: String,         message: Option<String>,     },     ChildAgent {         thread_id: ThreadId,         turn_id: TurnId,         agent_id: String,         child_session_id: String,         parent_session_id: Option<String>,         status: String,         message: Option<String>,     },     ChildScopedStream {         thread_id: ThreadId,         turn_id: TurnId,         agent_id: String,         child_session_id: String,         parent_session_id: Option<String>,         event: String,         seq: usize,         message: Option<String>,     },     ContextStatus {         thread_id: ThreadId,         turn_id: TurnId,         active_context_tokens: i64,         token_limit_reached: bool,         compacted: bool,         dropped_messages: usize,     },     StorageState {         thread_id: ThreadId,         turn_id: TurnId,         session_id: Option<String>,         parent_session_id: Option<String>,         rollout_items: usize,         rollout_truncated: bool,         #[serde(default)]         child_session_ids: Vec<String>,     },     FileChanged {         thread_id: ThreadId,         turn_id: TurnId,         path: String,         kind: String,     },     TurnCompleted {         thread_id: ThreadId,         turn_id: TurnId,     },     Cancelled {         thread_id: Option<ThreadId>,         turn_id: Option<TurnId>,         reason: Option<String>,     },     ProviderError {         thread_id: Option<ThreadId>,         turn_id: Option<TurnId>,         provider: String,         status: Option<u16>,         classification: String,         message: String,     },     Error {         thread_id: Option<ThreadId>,         turn_id: Option<TurnId>,         message: String,     }, }  #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)] pub struct VersionedRuntimeEvent {     pub protocol_version: ProtocolVersion,     pub event: RuntimeEvent, }  impl VersionedRuntimeEvent {     pub fn new(event: RuntimeEvent) -> Self {         Self {             protocol_version: ProtocolVersion::V1,             event,         }     } }  pub fn to_jsonl_line(event: &RuntimeEvent) -> Result<String, serde_json::Error> {     serde_json::to_string(event) }  pub fn to_versioned_jsonl_line(event: &RuntimeEvent) -> Result<String, serde_json::Error> {     serde_json::to_string(&VersionedRuntimeEvent::new(event.clone())) }  pub fn from_jsonl_line(line: &str) -> Result<RuntimeEvent, serde_json::Error> {     serde_json::from_str(line) }  pub fn from_versioned_jsonl_line(line: &str) -> Result<VersionedRuntimeEvent, serde_json::Error> {     serde_json::from_str(line) }  pub fn stream_event_to_runtime_event(event: StreamEvent) -> RuntimeEvent {     RuntimeEvent::Stream { event } }  pub fn response_text_delta(delta: impl Into<String>) -> ResponseItemDelta {     ResponseItemDelta::MessageContent {         item_id: None,         delta: delta.into(),     } }  #[cfg(test)] mod tests {     use super::*;      #[test]     fn protocol_event_round_trips_jsonl() {         let event = RuntimeEvent::ToolStarted {             thread_id: ThreadId("thread-1".to_string()),             turn_id: TurnId("turn-1".to_string()),             call: ToolCall::Shell {                 id: Some("call-1".to_string()),                 command: "echo yunxi".to_string(),             },         };          let line = to_jsonl_line(&event).expect("jsonl");         let parsed = from_jsonl_line(&line).expect("parsed event");          assert_eq!(parsed, event);     }      #[test]     fn stream_event_round_trips_through_runtime_event() {         let stream = StreamEvent::ItemDelta {             thread_id: ThreadId("thread-stream".to_string()),             turn_id: TurnId("turn-stream".to_string()),             delta: ResponseItemDelta::MessageContent {                 item_id: Some("message-1".to_string()),                 delta: "hello".to_string(),             },         };         let event = stream_event_to_runtime_event(stream.clone());          let line = to_jsonl_line(&event).expect("jsonl");         let parsed = from_jsonl_line(&line).expect("parsed event");          assert_eq!(parsed, RuntimeEvent::Stream { event: stream });     }      #[test]     fn turn_metadata_carries_workspace_and_policy_context() {         let mut metadata = TurnMetadata::new(             ThreadId("thread-1".to_string()),             TurnId("turn-1".to_string()),             "D:/YunXi Agent",         );         metadata.model = Some("yunxi-model".to_string());         metadata.approval_mode = Some("never".to_string());         metadata.sandbox_mode = Some("workspace-write".to_string());         metadata.workspaces.insert(             "D:/YunXi Agent".to_string(),             WorkspaceMetadata {                 associated_remote_urls: None,                 latest_git_commit_hash: Some("abc123".to_string()),                 has_changes: Some(true),             },         );          assert_eq!(metadata.thread_id.0, "thread-1");         assert_eq!(             metadata.workspaces["D:/YunXi Agent"].has_changes,             Some(true)         );     }      #[test]     fn approval_runtime_event_round_trips_jsonl() {         let event = RuntimeEvent::ApprovalRequested {             thread_id: ThreadId("thread-approval".to_string()),             turn_id: TurnId("turn-approval".to_string()),             call_id: Some("call-approval".to_string()),             tool_name: "shell".to_string(),             reason: "tool execution requires approval".to_string(),         };          let line = to_jsonl_line(&event).expect("jsonl");         let parsed = from_jsonl_line(&line).expect("parsed event");          assert_eq!(parsed, event);     }      #[test]     fn escalation_runtime_event_round_trips_jsonl() {         let event = RuntimeEvent::EscalationRequested {             thread_id: ThreadId("thread-escalation".to_string()),             turn_id: TurnId("turn-escalation".to_string()),             call_id: Some("call-escalation".to_string()),             tool_name: "shell".to_string(),             reason: "sandbox is read-only".to_string(),             required_sandbox: Some("workspace-write".to_string()),             required_network: None,         };          let line = to_jsonl_line(&event).expect("jsonl");         let parsed = from_jsonl_line(&line).expect("parsed event");          assert_eq!(parsed, event);     }      #[test]     fn versioned_runtime_event_round_trips_jsonl() {         let event = RuntimeEvent::TurnStarted {             thread_id: ThreadId("thread-versioned".to_string()),             turn_id: TurnId("turn-versioned".to_string()),         };          let line = to_versioned_jsonl_line(&event).expect("versioned jsonl");         let parsed = from_versioned_jsonl_line(&line).expect("parsed versioned event");          assert_eq!(parsed.protocol_version, ProtocolVersion::V1);         assert_eq!(parsed.event, event);     }      #[test]     fn deep_parity_runtime_events_round_trip_jsonl() {         let context = RuntimeEvent::ContextStatus {             thread_id: ThreadId("thread-context".to_string()),             turn_id: TurnId("turn-context".to_string()),             active_context_tokens: 120,             token_limit_reached: true,             compacted: true,             dropped_messages: 3,         };         let storage = RuntimeEvent::StorageState {             thread_id: ThreadId("thread-storage".to_string()),             turn_id: TurnId("turn-storage".to_string()),             session_id: Some("session-1".to_string()),             parent_session_id: Some("session-root".to_string()),             rollout_items: 8,             rollout_truncated: false,             child_session_ids: vec!["session-child".to_string()],         };          for event in [context, storage] {             let line = to_jsonl_line(&event).expect("jsonl");             let parsed = from_jsonl_line(&line).expect("parsed event");             assert_eq!(parsed, event);         }     }      #[test]     fn stage_4l_state_events_round_trip_jsonl() {         let mut data = BTreeMap::new();         data.insert("layer".to_string(), "stage_4l".to_string());         let thread_id = ThreadId("thread-stage-4l".to_string());         let turn_id = TurnId("turn-stage-4l".to_string());         let thread_state = RuntimeEvent::ThreadState {             thread_id: thread_id.clone(),             state: ThreadState {                 thread_id: thread_id.clone(),                 session_id: Some("session-stage-4l".to_string()),                 parent_thread_id: None,                 status: "running".to_string(),                 cwd: "D:/YunXi Agent".to_string(),                 resume_source: None,                 child_depth: 0,                 data: data.clone(),             },         };         let turn_state = RuntimeEvent::TurnState {             thread_id: thread_id.clone(),             turn_id: turn_id.clone(),             state: TurnState {                 phase: "tool_loop".to_string(),                 status: "running".to_string(),                 provider_status: "completed".to_string(),                 tool_loop_status: "dispatching".to_string(),                 cancellation_state: "not_cancelled".to_string(),                 data: data.clone(),             },         };         let deep_parity = RuntimeEvent::DeepParityState {             thread_id: thread_id.clone(),             turn_id: turn_id.clone(),             layer: "03_unified_exec".to_string(),             status: "ready".to_string(),             message: Some("unified exec facade represented".to_string()),             data: data.clone(),         };         let sandbox_attempt = RuntimeEvent::SandboxAttempt {             thread_id: thread_id.clone(),             turn_id: turn_id.clone(),             call_id: Some("call-1".to_string()),             platform: "windows".to_string(),             status: "ready".to_string(),             backend: "direct_process".to_string(),             command: Some("echo ok".to_string()),             cwd: "D:/YunXi Agent".to_string(),             message: None,         };         let approval_cache = RuntimeEvent::ApprovalCacheState {             thread_id,             turn_id,             session_id: Some("session-stage-4m".to_string()),             tool_name: "shell".to_string(),             key: "shell:echo ok:D:/YunXi Agent".to_string(),             decision: "approved".to_string(),             reused: true,         };          for event in [             thread_state,             turn_state,             deep_parity,             sandbox_attempt,             approval_cache,         ] {             let line = to_jsonl_line(&event).expect("jsonl");             let parsed = from_jsonl_line(&line).expect("parsed event");             assert_eq!(parsed, event);         }     } }